:root {
--radius-none: 0;
--radius-sm: 4px;      /* --radius--4 — 칩·코드 태그 */
--radius-md: 8px;      /* --radius--8, console --radius .5rem — 버튼·입력·카드 기본 */
--radius-lg: 12px;     /* --radius--12 — 큰 카드·모달 */
--radius-xl: 16px;     /* console --radius-lg 1rem — 제품 소개 카드 */
--radius-full: 9999px; /* --radius--999 — 마케팅 알약 버튼·아바타 */
--shadow-none: none;
--shadow-sm: 0 1px 2px hsl(220 30% 10% / .10);                                         /* 입력·작은 버튼 */
--shadow-md: 0 4px 6px -1px hsl(220 30% 10% / .08), 0 2px 4px -2px hsl(220 30% 10% / .08); /* 카드 hover, 드롭다운 */
--shadow-lg: 0 10px 15px -3px hsl(220 30% 10% / .10), 0 4px 6px -4px hsl(220 30% 10% / .10); /* 팝오버 */
--shadow-xl: 0 20px 25px -5px hsl(220 30% 10% / .15), 0 8px 10px -6px hsl(220 30% 10% / .15); /* 모달(--modal-shadow) */
--duration-fast: 150ms;
--duration-base: 300ms;
--duration-slow: 500ms;
--ease-out: cubic-bezier(0, 0, 0.2, 1);       /* (추정) */
--ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);  /* (추정) */
}
:root {
  /* Primary - Upstage Brand (다크에서도 --primary = brand-500) */
  --color-primary-50:  #EBEFFF;
  --color-primary-100: #DBE2FF;
  --color-primary-200: #C2CBFF;  /* --accent-foreground (다크) */
  --color-primary-300: #99A5FF;  /* 다크 강조 텍스트 */
  --color-primary-400: #7578FF;  /* --link-hover (다크) */
  --color-primary-500: #5B52FF;  /* primary 버튼·포커스 링 */
  --color-primary-600: #4D34F4;
  --color-primary-700: #442AD8;
  --color-primary-800: #3725AD;
  --color-primary-900: #322790;  /* --accent (다크) */
  --color-primary-950: #1E1650;  /* --primary-background (다크) */

  /* Secondary - Green-yellow */
  --color-secondary-200: #F3FF99;
  --color-secondary-500: #D2FF95;
  --color-secondary-900: #226B00;

  /* Neutral - Slate (값은 같고 쓰임이 뒤집힌다) */
  --color-neutral-0:    #FFFFFF;
  --color-neutral-50:   #F8FAFC;  /* 다크 본문 글자 */
  --color-neutral-100:  #F1F5F9;
  --color-neutral-200:  #E2E8F0;
  --color-neutral-300:  #CBD5E1;
  --color-neutral-500:  #64748B;  /* 비활성 글자 */
  --color-neutral-700:  #334155;  /* 중간 테두리 */
  --color-neutral-900:  #0F172A;  /* 카드·사이드바 강조 */
  --color-neutral-1000: #020617;  /* 다크 배경 */

  /* Semantic (다크 --state-*) */
  --color-success-bg: #02261C;  /* 163 88% 8% */
  --color-success-fg: #00AD82;  /* green-400 */
  --color-warning-bg: #291B00;  /* 39 100% 8% */
  --color-warning-fg: #FFA724;  /* yellow-400 */
  --color-error-bg:   #260309;  /* 350 86% 8% */
  --color-error-fg:   #FF3859;  /* red-400 */
  --color-info-bg:    #001B29;  /* 201 100% 8% */
  --color-info-fg:    #4483CA;  /* blue-400 */

  /* Surface */
  --bg-base:     #020617;              /* --background (neutral-950) */
  --bg-subtle:   #0F172A;              /* --subtle, 사이드바 선택 */
  --bg-elevated: #0F172A;              /* --card (neutral-900) */
  --bg-overlay:  rgba(0, 0, 0, 0.60);  /* --overlay 0 0% 0% / .6 */
  --bg-hero:     #0A0D14;

  /* Text */
  --text-primary:    #F8FAFC;  /* --foreground (neutral-50) */
  --text-secondary:  #CBD5E1;  /* (추정) */
  --text-tertiary:   #94A3B8;  /* --muted-foreground (neutral-400) */
  --text-on-primary: #FFFFFF;
  --text-disabled:   #64748B;  /* --disabled-foreground (neutral-500) */

  /* Border */
  --border-default: #1E293B;  /* --border (neutral-800) */
  --border-subtle:  #0F172A;  /* --border-subtle (neutral-900) */
  --border-strong:  #64748B;
  --border-focus:   #5B52FF;
}

[data-theme="light"] {
  --bg-base: #FFFFFF; --bg-subtle: #F8FAFC; --bg-elevated: #FFFFFF; --bg-overlay: rgba(30, 41, 59, 0.50);
  --text-primary: #0F172A; --text-secondary: #475569; --text-tertiary: #64748B; --text-disabled: #CBD5E1;
  --border-default: #E2E8F0; --border-subtle: #F1F5F9; --border-strong: #64748B;
  --color-success-bg: #ECFDF7; --color-success-fg: #066046; --color-warning-bg: #FFF9E5; --color-warning-fg: #8A5A00;
  --color-error-bg: #FFF0F1; --color-error-fg: #8A0A20; --color-info-bg: #F0F9FF; --color-info-fg: #005A8A;
}




.btn { height: 36px; padding: 0 16px; border-radius: var(--radius-md); font: 500 14px/1 Geist, 'Noto Sans KR', sans-serif; border: 1px solid transparent; transition: background var(--duration-fast) var(--ease-out); cursor: pointer; }
.btn-primary { background: var(--color-primary-500); color: var(--text-on-primary); }
.btn-primary:hover { background: var(--color-primary-600); }
.btn-primary:active { background: var(--color-primary-700); }
.btn-primary:disabled { background: var(--color-neutral-100); color: var(--text-disabled); cursor: not-allowed; }
.btn-primary.is-loading { color: transparent; position: relative; } /* 가운데 16px 스피너, 흰색 2px 테두리 */
.btn-secondary { background: var(--bg-base); color: var(--text-primary); border-color: var(--border-default); }
.btn-secondary:hover { background: var(--bg-subtle); border-color: var(--color-neutral-300); }
.btn-secondary:active { background: var(--color-neutral-100); }
.btn-secondary:disabled { color: var(--text-disabled); border-color: var(--border-subtle); }
.btn-ghost { background: transparent; color: var(--text-secondary); }
.btn-ghost:hover { background: var(--color-neutral-100); color: var(--text-primary); }
.btn-ghost:active { background: var(--color-neutral-200); }
.btn-danger { background: #FF3859; color: #FFFFFF; }            /* --destructive */
.btn-danger:hover { background: #E8304F; }                       /* (추정) */
.btn-danger:disabled { background: var(--color-error-bg); color: #FFB3BF; }
.btn-pill { border-radius: var(--radius-full); padding: 0 20px; } /* 마케팅 사이트 CTA */
.input { height: 36px; padding: 0 12px; border: 1px solid var(--border-default); border-radius: var(--radius-md); background: var(--bg-base); color: var(--text-primary); font-size: 14px; }
.input::placeholder { color: var(--text-tertiary); }
.input:hover { border-color: var(--color-neutral-300); }            /* --input-hover */
.input:focus { outline: none; border-color: var(--color-primary-500); box-shadow: 0 0 0 3px rgba(91, 82, 255, .20); } /* --input-active + ring 50% */
.input.is-error { border-color: #FF3859; box-shadow: 0 0 0 3px rgba(255, 56, 89, .20); }
.input:disabled { background: var(--color-neutral-100); color: var(--text-disabled); border-color: var(--border-subtle); }
.card { background: var(--bg-elevated); border: 1px solid var(--border-subtle); border-radius: var(--radius-lg); padding: 24px; }
.card-emphasis { background: var(--color-primary-50); border-color: var(--color-primary-300); }   /* --accent / --accent-border */
.card-outlined { background: transparent; border: 1px solid var(--border-default); }
.card:hover { box-shadow: var(--shadow-md); }
.badge { display: inline-flex; align-items: center; height: 22px; padding: 0 8px; border-radius: var(--radius-sm); font: 500 12px/1 Geist, sans-serif; }
.badge-solid { background: var(--color-neutral-900); color: #FFFFFF; }                 /* --badge-default */
.badge-new { background: var(--color-secondary-500); color: var(--color-neutral-900); } /* 메뉴 "New" 라임 */
.badge-subtle { background: var(--color-primary-50); color: var(--color-primary-800); }
.badge-outline { border: 1px solid var(--border-default); color: var(--text-secondary); }
.gnb { height: 56px; display: flex; align-items: center; gap: 24px; padding: 0 16px; background: var(--bg-subtle); border-bottom: 1px solid var(--border-subtle); }
.gnb-link { font-size: 14px; font-weight: 500; color: var(--text-tertiary); }
.gnb-link.is-active { color: var(--text-primary); }
.sidebar { width: 240px; background: var(--bg-subtle); border-right: 1px solid var(--border-subtle); padding: 12px; }
.sidebar-heading { font-size: 12px; font-weight: 600; color: var(--text-tertiary); padding: 12px 8px 4px; }
.sidebar-item { display: block; padding: 6px 8px; border-radius: var(--radius-md); font-size: 14px; color: #475569; }  /* --sidebar-foreground */
.sidebar-item:hover, .sidebar-item.is-active { background: var(--color-neutral-200); color: var(--text-primary); } /* --sidebar-item-highlight */
